function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e08a72");
  let grassColor = "#8aa461";
  fill(grassColor);
  brush.fillTexture(1, 0);
  brush.fill(grassColor, 1);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.endShape(true);

  let peaksColor = "#e87e48";
  brush.fillTexture(0.5, 0);
  brush.fill(peaksColor, 1);
  brush.circle(200, 100, 40);
  brush.vertex(150, 150);
  brush.vertex(250, 150);
  brush.vertex(200, 200);
  brush.endShape(true);

  let skyColor = "#0d6892";
  fill(skyColor);
  brush.fillTexture(0.5, 0);
  brush.fill(skyColor, 1);
  brush.vertex(200, 0);
  brush.vertex(200, 400);
  brush.endShape(true);
}
