function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  //Horizon at 200 units long, rain falling into the sunset
  drawVerticalStripe("#e6b033", 200);

  //The land to the left of the ocean 
  brush.fill("#517248");
  brush.fillBleed(0.5);
  brush.beginShape("soft");
  brush.vertex(-200, 0);
  brush.vertex(-200, 180);
  brush.vertex(-200, 200);
  brush.vertex(-40, 180);
  brush.vertex(-40, 30);
  brush.vertex(-200, 0);
  brush.endShape();

  //Render edges of the ground
  brush.fill("#445544");
  brush.fillTexture(1, 1);
  brush.beginShape("rectangle");
  brush.vertex(-40, 0);
  brush.vertex(40, 0);
  brush.vertex(40, 200);
  brush.vertex(-40, 200);
  brush.endShape(true);

  //The ground on the far left of the ocean
  brush.fill("#394141");
  brush.beginShape("rectangle");
  brush.vertex(-40, 0);
  brush.vertex(40, 0);
  brush.vertex(40, 200);
  brush.vertex(-40, 200);
  brush.endShape(true);

  //Color code for eye 
  brush.fillBleed(1);
  brush.drawCircle(160, 200, 80);

  //Paint a small red dot to represent the sun on the land
  brush.fill("#fa3d4e");
  brush.drawCircle(160, 200, 20);
}

