const soloRender = false;
if (soloRender) {
  require('./frame_processor.js');
}

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  if (!soloRender) { return; }

  background('#d8e3d2');
  brush.fillBleed(0.6);
  brush.circle(200, 200, 50);

  // sunset's radius 100px
  brush.fill(0.5);
  for (let x = 0; x < 400; x += 20) {
    brush.circle(x, 200, 20);
  }

  brush.fill(0.25);
  brush.beginShape();
  brush.vertex(0, 140);
  brush.vertex(200, 100);
  brush.vertex(400, 140);
  brush.endShape(true);

  brush.fill(0.25);
  brush.beginShape();
  brush.vertex(0, 160);
  brush.vertex(100, 100);
  brush.vertex(400, 160);
  brush.endShape(true);
}
