import '@p5/brush';

let mountainHill;
let tree;
let flower;

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  background("#f4efe4");
  setupTrees();
  setupFlowers();
}

function draw() {
  translate(-width / 2, -height / 2);
  gridWithAxes();
  background("#e5c787");
  mountainHill();
  hill();
  tree();
  flower();
}

function setupTrees() {
  mountainHill = createCube(200, 60, 200, 200);
  tree = new Tree();
  tree.setSize(100, 50);
  tree.setWidth(30, 10);
  tree.setHeight(10);
  tree.setAlpha(0, 100);
  tree.setColor("#9C0D88", 0, 100);
}

function setupFlowers() {
  flower = new Flower();
  flower.setWidth(12, 50);
  flower.setHeight(6);
  flower.setAlpha(20, 100);
  flower.setColor("#9C0D88", 20, 100);
  flower.setDiameter(10);
  flower.setRotation(10);
}

function gridWithAxes() {
  // grid lines
  for (var i = -120; i <= 120; i += 10) {
    for (var j = -120; j <= 120; j += 10) {
      if (i === 0 || j === 0) {
        // Axes
        stroke("#d0d0c0");
        line(i, -j, i, j);
        line(j, 0, i, -j);
      } else if (i === 0) {
        // X axis
        stroke("#7f7f7f");
        line(i, -j, i, j);
      } else if (j === 0) {
        // Y axis
        stroke("#7f7f7f");
        line(-i, j, j, j);
      }
    }
  }
}

