function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // 1st Brush - Sky - Blue
  brush.fill("#73c9e0", 30);
  brush.circle(0, 400, 250);  // 0, 400, radius 250 
  brush.fill("#2c6e8b", 30);
  brush.circle(0, 150, 250);
  brush.fill("#5b81a3", 50); 
  brush.circle(100, 0, 250);
  brush.fill("#4b6c77", 50); 
  brush.circle(-100, 0, 250);

  // 2nd Brush - Grass - Green
  brush.fill("#50ae40", 50);
  brush.beginShape();
  brush.vertex(-100, -200);
  brush.vertex(0, -200);
  brush.vertex(100, -200);
  brush.endShape();

  // 3rd Brush - Ant Hill (Fast)
  brush.fill("#78b297", 50); 
  brush.beginShape();
  brush.vertex(-100, -200);
  brush.vertex(0, -200);
  brush.vertex(-100, -50);
  brush.endShape();
  brush.fill("#78b297", 50); 
  brush.beginShape();
  brush.vertex(-100, -200);
  brush.vertex(-0, -150);
  brush.vertex(100, -150);
  brush.endShape();

  // 4th Brush - Hills - Green Dark
  brush.fill("#34672f", 50); 
  brush.beginShape();
  brush.vertex(-300, -200);
  brush.vertex(-300, -250);
  brush.vertex(-400, -250);
  brush.vertex(-400, -200);
  brush.endShape();

  // 5th Brush - Sky Line - Blue Gray
  brush.fill("#536b74", 10);
  brush.fillTexture(0.3, 0.25);
  brush.beginShape();
  brush.vertex(0, 400);
  brush.vertex(-250, 50);
  brush.vertex(-250, 150);
  brush.vertex(-200, 250);
  brush.vertex(-200, 350);
  brush.vertex(-100, 350);
  brush.end

